const entry = msg.payload;

msg.payload = {
    id:        entry.id,
    text:      entry.text             || "",
    timestamp: entry.timeCreated,
    author:    entry.loggedByFullName || "",
    files:     entry.files            || [],
    labels:    entry.labels           || []
};

return msg;

const entry = msg.payload;

const isLocation = entry.location === true;
let text = entry.content || "";
let geo = null;

if (isLocation) {
    try {
        const geojson = JSON.parse(entry.content);
        const [lng, lat] = geojson.geometry.coordinates;
        geo = { lat, lng };
        var description = geojson.properties && geojson.properties.description ? geojson.properties.description : "";
        var mapsLink = "Klikk her for å åpne i Google Maps: https://www.google.com/maps?q=" + lat + "%2C" + lng;
        text = description ? description + "\n\n" + mapsLink : mapsLink;
    } catch (e) {
        text = entry.content || "";
    }
}

msg.payload = {
    id: entry.id,
    text: text,
    timestamp: new Date(entry.createdAt).getTime(),
    author: entry.username || "",
    files: entry.files || [],
    labels: []
};

msg.geo = geo;
msg.isLocation = isLocation;

return msg;

msg.bridgeEntry = msg.payload;

var lat = msg.geo.lat;
var lng = msg.geo.lng;
var zoom = 15;

var latRad = lat * Math.PI / 180;
var n = Math.pow(2, zoom);
var tileX = Math.floor((lng + 180) / 360 * n);
var tileY = Math.floor((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * n);

var exactX = (lng + 180) / 360 * n;
var exactY = (1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * n;
var markerPixelX = Math.round((exactX - tileX + 1) * 256);
var markerPixelY = Math.round((exactY - tileY + 1) * 256);

var tiles = [];
for (var dy = -1; dy <= 1; dy++) {
    for (var dx = -1; dx <= 1; dx++) {
        tiles.push({
            url: "https://tile.openstreetmap.org/" + zoom + "/" + (tileX + dx) + "/" + (tileY + dy) + ".png",
            x: (dx + 1) * 256,
            y: (dy + 1) * 256
        });
    }
}

msg.tiles = tiles;
msg.markerPixelX = markerPixelX;
msg.markerPixelY = markerPixelY;

return msg;

var tiles = msg.tiles;

function fetchTile(url) {
    return new Promise(function(resolve, reject) {
        https.get(url, { headers: { "User-Agent": "Parat-Bridge/1.0" } }, function(res) {
            var chunks = [];
            res.on("data", function(chunk) { chunks.push(chunk); });
            res.on("end", function() { resolve(Buffer.concat(chunks)); });
            res.on("error", reject);
        }).on("error", reject);
    });
}

var promises = tiles.map(function(t) { return fetchTile(t.url); });

Promise.all(promises).then(function(buffers) {
    var composites = buffers.map(function(buf, i) {
        return { input: buf, left: tiles[i].x, top: tiles[i].y };
    });

    var markerSize = 16;
    var markerSvg = Buffer.from(
        '<svg width="' + markerSize + '" height="' + markerSize + '">' +
        '<circle cx="8" cy="8" r="7" fill="red" stroke="white" stroke-width="2"/>' +
        '</svg>'
    );

    composites.push({
        input: markerSvg,
        left: msg.markerPixelX - markerSize / 2,
        top: msg.markerPixelY - markerSize / 2
    });

    return sharp({ create: { width: 768, height: 768, channels: 4, background: { r: 200, g: 200, b: 200, alpha: 1 } } })
        .composite(composites)
        .resize(800)
        .jpeg({ quality: 80 })
        .toBuffer();
}).then(function(jpegBuffer) {
    msg.payload = msg.bridgeEntry;
    msg.payload.files = [{
        name: "location_" + Date.now() + ".jpg",
        type: "image/jpeg",
        buffer: jpegBuffer
    }];
    delete msg.bridgeEntry;
    delete msg.tiles;
    delete msg.markerPixelX;
    delete msg.markerPixelY;
    delete msg.geo;
    delete msg.isLocation;
    node.send(msg);
}).catch(function(err) {
    node.error("Map generation failed: " + err.message, msg);
});

return null;

const tmpIn = `/tmp/map_${Date.now()}.png`;
const tmpOut = `/tmp/map_${Date.now()}.jpg`;

msg.tmpIn = tmpIn;
msg.tmpOut = tmpOut;

fs.writeFileSync(tmpIn, msg.payload);

msg.payload = `-y -i ${tmpIn} -q:v 8 -vf scale=800:-1 -update 1 ${tmpOut}`;

return msg;

var compressed = fs.readFileSync(msg.tmpOut);

try { fs.unlinkSync(msg.tmpIn); } catch (e) { }
try { fs.unlinkSync(msg.tmpOut); } catch (e) { }

msg.payload = msg.bridgeEntry;
msg.payload.files = [{
    name: "location_" + Date.now() + ".jpg",
    type: "image/jpeg",
    buffer: compressed
}];

delete msg.bridgeEntry;
delete msg.tmpIn;
delete msg.tmpOut;
delete msg.geo;
delete msg.isLocation;

return msg;
